import sqlite3
import time
import logging
import os
import requests as req

logger = logging.getLogger('backup_worker')
logging.basicConfig(level=logging.INFO, format='%(asctime)s %(name)s %(levelname)s %(message)s')


def run(db_path: str):
    dt_url = os.environ['DT_URL'].rstrip('/')
    library_id = os.environ.get('DT_LIBRARY_ID', 'main')
    username = os.environ.get('DT_USERNAME', '')
    password = [REDACTED]'DT_PASSWORD', '')

    session = req.Session()

    def login():
        try:
            session.post(
                f'{dt_url}/',
                data={
                    'username': username,
                    'password': password,
                    'redirectBackTo': f'{dt_url}/?library={library_id}',
                },
                timeout=10,
                allow_redirects=True,
            )
            logger.info('Logged in to DT')
        except Exception as e:
            logger.error(f'DT login failed: {e}')

    def is_login_page(resp):
        return 'text/html' in resp.headers.get('content-type', '')

    def post_timeline(payload):
        resp = session.post(f'{dt_url}/timeline', json=payload, timeout=10)
        if is_login_page(resp):
            login()
            resp = session.post(f'{dt_url}/timeline', json=payload, timeout=10)
        resp.raise_for_status()
        return resp.json()

    def post_tag(timeline_id, tag):
        payload = {'libraryId': library_id, 'op': 'add', 'tag': tag, 'type': 'tag'}
        resp = session.post(f'{dt_url}/timeline/{timeline_id}/tag', json=payload, timeout=10)
        if is_login_page(resp):
            login()
            resp = session.post(f'{dt_url}/timeline/{timeline_id}/tag', json=payload, timeout=10)
        if not resp.ok:
            raise Exception(f'{resp.status_code} {resp.text}')

    def delete_timeline(timeline_id):
        resp = session.delete(f'{dt_url}/timeline/{timeline_id}', params={'libraryId': library_id}, timeout=10)
        if is_login_page(resp):
            login()
            resp = session.delete(f'{dt_url}/timeline/{timeline_id}', params={'libraryId': library_id}, timeout=10)
        resp.raise_for_status()

    login()
    counter = 0

    while True:
        try:
            _run_watch_later_cleanup_loop(db_path, delete_timeline)
        except Exception as e:
            logger.error(f'Watch Later cleanup loop error: {e}')

        try:
            _run_submission_loop(db_path, dt_url, library_id, session, post_tag)
        except Exception as e:
            logger.error(f'Submission loop error: {e}')

        try:
            _run_tagging_loop(db_path, library_id, post_tag)
        except Exception as e:
            logger.error(f'Tagging loop error: {e}')

        if counter % 10 == 9:
            try:
                _run_polling_loop(db_path, library_id, post_timeline)
            except Exception as e:
                logger.error(f'Polling loop error: {e}')

        counter += 1
        time.sleep(30)


def _run_watch_later_cleanup_loop(db_path, delete_timeline):
    db = sqlite3.connect(db_path, timeout=10)
    db.execute('PRAGMA journal_mode=WAL')
    db.row_factory = sqlite3.Row
    try:
        videos = db.execute(
            "SELECT v.id, v.dt_timeline_id, "
            "EXISTS("
            "    SELECT 1 FROM videos v2 "
            "    LEFT JOIN playlists p2 ON p2.id = v2.playlist_id "
            "    WHERE v2.source = v.source AND p2.name != 'Watch Later'"
            ") as in_other_playlist "
            "FROM videos v "
            "LEFT JOIN playlists p ON p.id = v.playlist_id "
            "WHERE v.dt_timeline_id IS NOT NULL "
            "AND p.name = 'Watch Later'"
        ).fetchall()

        for video in videos:
            try:
                if not video['in_other_playlist']:
                    delete_timeline(video['dt_timeline_id'])
                    logger.info(f'Deleted Watch Later video {video["id"]} from DT (timeline {video["dt_timeline_id"]})')
                else:
                    logger.info(f'Watch Later video {video["id"]} skipped DT delete - URL exists in another playlist')
                db.execute(
                    'UPDATE videos SET dt_timeline_id = NULL, dt_status = NULL WHERE id = ?',
                    (video['id'],),
                )
                db.commit()
            except Exception as e:
                logger.error(f'Error removing Watch Later video {video["id"]} from DT: {e}')
    finally:
        db.close()


def _run_submission_loop(db_path, dt_url, library_id, session, post_tag):
    db = sqlite3.connect(db_path, timeout=10)
    db.execute('PRAGMA journal_mode=WAL')
    db.row_factory = sqlite3.Row
    try:
        videos = db.execute(
            "SELECT v.id, v.source, p.name as playlist_name "
            "FROM videos v "
            "LEFT JOIN playlists p ON p.id = v.playlist_id "
            "WHERE v.dt_timeline_id IS NULL "
            "AND (v.source LIKE '%youtube.com%' OR v.source LIKE '%youtu.be%') "
            "AND p.name != 'Watch Later'"
        ).fetchall()

        if not videos:
            return

        resp = session.post(
            f'{dt_url}/add-to-queue',
            json={'libraryId': library_id, 'link': [v['source'] for v in videos]},
            timeout=30,
        )
        resp.raise_for_status()
        results = resp.json()

        for video, result in zip(videos, results):
            try:
                if 'timelineId' in result:
                    timeline_id = result['timelineId']
                elif result.get('error') == 'Link already exists':
                    timeline_id = result.get('timelineId')
                    if not timeline_id:
                        logger.warning(f'Could not find existing DT item for: {video["source"]}')
                        continue
                else:
                    logger.warning(f'Unexpected response from add-to-queue: {result}')
                    continue

                db.execute(
                    'UPDATE videos SET dt_timeline_id = ? WHERE id = ?',
                    (timeline_id, video['id']),
                )
                db.commit()
                logger.info(f'Submitted video {video["id"]} -> DT item {timeline_id}')

                tagged, _ = _apply_tags(timeline_id, video['playlist_name'], post_tag)
                if tagged:
                    db.execute('UPDATE videos SET dt_tagged = 1 WHERE id = ?', (video['id'],))
                    db.commit()
            except Exception as e:
                logger.error(f'Error processing submission result for video {video["id"]}: {e}')
    finally:
        db.close()


def _apply_tags(timeline_id, playlist_name, post_tag):
    tags = ['Added by WVP'] + ([f'WVP:{playlist_name}'] if playlist_name else [])
    success = True
    errors = []
    for tag in tags:
        try:
            post_tag(timeline_id, tag)
            logger.info(f'Tagged DT item {timeline_id} with {tag}')
        except Exception as e:
            logger.error(f'Error tagging DT item {timeline_id} with {tag}: {e}')
            success = False
            errors.append(str(e))
    return success, errors


def _run_tagging_loop(db_path, library_id, post_tag):
    db = sqlite3.connect(db_path, timeout=10)
    db.execute('PRAGMA journal_mode=WAL')
    db.row_factory = sqlite3.Row
    try:
        videos = db.execute(
            "SELECT v.id, v.dt_timeline_id, v.source, v.title, p.name as playlist_name "
            "FROM videos v "
            "LEFT JOIN playlists p ON p.id = v.playlist_id "
            "WHERE v.dt_timeline_id IS NOT NULL AND v.dt_tagged IS NULL"
        ).fetchall()

        for video in videos:
            tagged, errors = _apply_tags(video['dt_timeline_id'], video['playlist_name'], post_tag)
            if tagged:
                db.execute('UPDATE videos SET dt_tagged = 1 WHERE id = ?', (video['id'],))
                db.commit()
            elif any('FOREIGN KEY' in e for e in errors):
                logger.warning(f'DT item {video["dt_timeline_id"]} no longer exists, clearing for video {video["id"]} "{video["title"]}" ({video["source"]}) to resubmit')
                db.execute('UPDATE videos SET dt_timeline_id = NULL, dt_status = NULL WHERE id = ?', (video['id'],))
                db.commit()
    finally:
        db.close()


def _run_polling_loop(db_path, library_id, post_timeline):
    db = sqlite3.connect(db_path, timeout=10)
    db.execute('PRAGMA journal_mode=WAL')
    db.row_factory = sqlite3.Row
    try:
        videos = db.execute(
            "SELECT id, dt_timeline_id FROM videos "
            "WHERE dt_timeline_id IS NOT NULL "
            "AND (dt_status IS NULL OR dt_status != 'downloaded')"
        ).fetchall()

        if not videos:
            return

        ids = [v['dt_timeline_id'] for v in videos]
        data = post_timeline({
            'libraryId': library_id,
            'search': 'id:' + ','.join(str(i) for i in ids),
            'pageSize': len(ids),
        })
        items_by_id = {item['id']: item for item in data.get('timeline', [])}

        for video in videos:
            item = items_by_id.get(video['dt_timeline_id'])
            if item:
                db.execute(
                    'UPDATE videos SET dt_status = ? WHERE id = ?',
                    (item['status'], video['id']),
                )
                logger.info(f'Polled video {video["id"]}: dt_status = {item["status"]}')
            else:
                logger.warning(f'DT item {video["dt_timeline_id"]} not found during polling')
        db.commit()
    except Exception as e:
        logger.error(f'Error during polling: {e}')
    finally:
        db.close()

from dotenv import load_dotenv
load_dotenv()

from flask import Flask, jsonify, g, request
import os
import sqlite3
from operator import itemgetter
import threading
import backup_worker
import db_setup

app = Flask(__name__)

app.database = 'store.db'
app.database = os.path.join(os.path.dirname(__file__), app.database)
app.debug = False

db_setup.setup(app.database)

videos_table_columns = ['title', 'description', 'thumbnail', 'duration', 'uploader', 'uploader_url', 'published_at', 'source', 'note', 'tags', 'playlist_id']
playlists_table_columns = ['name', 'description']

@app.route('/')
def index():
    return app.send_static_file('index.html')

@app.route('/videos')
def get_videos():
    return get_all('SELECT * FROM videos ORDER BY updated_at DESC')

@app.route('/videos/<playlist_id>')
def get_videos_for_playlist(playlist_id):
    return get_all('SELECT * FROM videos WHERE playlist_id=? ORDER BY updated_at DESC', [playlist_id])

@app.route('/add-video', methods=['POST'])
def add_video():
    success = insert(request, 'videos', videos_table_columns)
    if success:
        return jsonify(status='success', message='Video Added')
    else:
        return jsonify(status='error', message="Video Couldn't be Added")

@app.route('/edit-video', methods=['POST'])
def edit_video():
    success = update(request, 'videos', videos_table_columns)
    if success:
        return jsonify(status='success', message='Video Updated')
    else:
        return jsonify(status='error', message="Video Couldn't be Updated")

@app.route('/delete-video', methods=['POST'])
def delete_video():
    success = delete(request, 'videos')
    if success:
        return jsonify(status='success', message='Video Deleted')
    else:
        return jsonify(status='error', message="Video Couldn't be Deleted")

@app.route('/playlists')
def get_playlists():
    g.db = connect_db()
    g.db.row_factory = make_dicts
    videos = g.db.execute('SELECT * FROM videos')
    videos = videos.fetchall()
    playlists = g.db.execute('SELECT * FROM playlists')
    playlists = playlists.fetchall()
    g.db.close()

    videos_playlists = dict()
    for video in videos:
        if video['playlist_id'] in videos_playlists:
            videos_playlists[video['playlist_id']].append(video)
        else:
            videos_playlists[video['playlist_id']] = list()
            videos_playlists[video['playlist_id']].append(video)

    playlist_ids_by_latest_video = list()

    for videos_playlist in videos_playlists:
        max_dict_in_list = max(videos_playlists[videos_playlist], key=itemgetter('updated_at'))
        custom_dict = dict()
        custom_dict['id'] = max_dict_in_list['playlist_id']
        custom_dict['updated_at:1'] = max_dict_in_list['updated_at']
        playlist_ids_by_latest_video.append(custom_dict)

    playlists_by_latest_video = list()
    for playlist_id_by_latest_video in playlist_ids_by_latest_video:
        for playlist in playlists:
            if playlist['id'] == playlist_id_by_latest_video['id']:
                playlists_by_latest_video.append({**playlist_id_by_latest_video, **playlist})

    playlists_by_latest_video_sorted_desc = sorted(playlists_by_latest_video, key=itemgetter('updated_at:1'), reverse=True)

    # missing_playlists aka playlists with no videos added to them yet, so there's no latest video, hence the missing tag
    missing_playlists = list()
    for playlist in playlists:
        this_playlist_found = False
        for playlist_by_latest_video_sorted_desc in playlists_by_latest_video_sorted_desc:
            if playlist['id'] == playlist_by_latest_video_sorted_desc['id']:
                this_playlist_found = True
                break
        if this_playlist_found is False:
            missing_playlists.append(playlist)

    final_playlists = playlists_by_latest_video_sorted_desc + missing_playlists

    # if len(playlists) == len(final_playlists):
    #     print("total playlists are equal - yay! :)")
    # else:
    #     print("total playlists are unequal - nay :(")

    return jsonify(final_playlists)

@app.route('/playlist/<id>')
def get_playlist(id):
    return get_one('SELECT name FROM playlists WHERE id =?', [id])

@app.route('/add-playlist', methods=['POST'])
def add_playlist():
    success = insert(request, 'playlists', playlists_table_columns)
    if success:
        return jsonify(status='success', message='Playlist Added')
    else:
        return jsonify(status='error', message="Playlist Couldn't be Added")

@app.route('/edit-playlist', methods=['POST'])
def edit_playlist():
    success = update(request, 'playlists', playlists_table_columns)
    if success:
        return jsonify(status='success', message='Playlist Updated')
    else:
        return jsonify(status='error', message="Playlist Couldn't be Updated")

@app.route('/delete-playlist', methods=['POST'])
def delete_playlist():
    success = delete(request, 'playlists')
    if success:
        return jsonify(status='success', message='Playlist Deleted')
    else:
        return jsonify(status='error', message="Playlist Couldn't be Deleted")

@app.route('/url-exists-in-playlist')
def url_exists_in_playlist():
    g.db = connect_db()
    g.db.row_factory = make_dicts
    videos = g.db.execute('SELECT playlist_id FROM videos WHERE source LIKE ?', [request.args.get('url') + '%']).fetchall()
    found_in_playlists = []
    for video in videos:
        found_in_playlists.append(g.db.execute('SELECT name FROM playlists WHERE id = ?', [video['playlist_id']]).fetchone()['name'])
    g.db.close()
    return jsonify(found_in_playlists)

@app.route('/dt-config')
def dt_config():
    dt_url = os.environ.get('DT_URL')
    if not dt_url:
        return jsonify(enabled=False)
    return jsonify(
        enabled=True,
        url=dt_url,
        libraryId=os.environ.get('DT_LIBRARY_ID', 'main')
    )

def connect_db():
    return sqlite3.connect(app.database, timeout=10)

def insert(request, table_name, table_columns):
    table_columns_dict = {}
    if request.get_json() == None:
        for table_column in table_columns:
            if request.form.get(table_column) != None:
                table_columns_dict[table_column] = request.form.get(table_column)
    else:
        for table_column in table_columns:
            if table_column in request.get_json():
                table_columns_dict[table_column] = request.get_json()[table_column]
    fields = ",".join(table_columns_dict.keys())
    question_marks = ','.join(list('?'*len(table_columns_dict)))
    values = list(table_columns_dict.values())
    try:
        g.db = connect_db()
        g.db.execute(f'INSERT into {table_name}({fields}) VALUES({question_marks})', values)
        g.db.commit()
        g.db.close()
    except Exception as e:
        print(e)
        return False
    return True

def update(request, table_name, table_columns):
    table_columns_dict = {}
    if request.get_json() == None:
        for table_column in table_columns:
            if request.form.get(table_column) != None:
                table_columns_dict[table_column] = request.form.get(table_column)
        if request.form.get('id') != None:
            id = request.form.get('id')
        else:
            return False # if id is empty
    else:
        for table_column in table_columns:
            if table_column in request.get_json():
                table_columns_dict[table_column] = request.get_json()[table_column]
        if 'id' in request.get_json():
            id = request.get_json()['id']
        else:
            return False
    fields = "=?,".join(table_columns_dict.keys()) + "=?"
    values = list(table_columns_dict.values())
    values.append(id)
    try:
        g.db = connect_db()
        g.db.execute(f'UPDATE {table_name} SET {fields}, updated_at=CURRENT_TIMESTAMP WHERE id=?', values)
        g.db.commit()
        g.db.close()
    except Exception as e:
        print(e)
        return False
    return True

def delete(request, table_name):
    if request.get_json() == None:
        if request.form.get('id') != None:
            id = request.form.get('id')
        else:
            return False
    else:
        if 'id' in request.get_json():
            id = request.get_json()['id']
        else:
            return False
    try:
        g.db = connect_db()
        g.db.execute(f'DELETE FROM {table_name} WHERE id=?', [id])
        g.db.commit()
        g.db.close()
    except Exception as e:
        print(e)
        return False
    return True

def get_one(query, query_params):
    g.db = connect_db()
    g.db.row_factory = make_dicts
    row = g.db.execute(query, query_params)
    row = row.fetchone()
    g.db.close()
    return jsonify(row)

def get_all(query, query_params=None):
    g.db = connect_db()
    g.db.row_factory = make_dicts
    if query_params is not None:
        rows = g.db.execute(query, query_params)
    else:
        rows = g.db.execute(query)
    rows = rows.fetchall()
    g.db.close()
    return jsonify(rows)

def make_dicts(cursor, row):
    return dict((cursor.description[idx][0], value)
                for idx, value in enumerate(row))

if os.environ.get('DT_URL'):
    _worker_thread = threading.Thread(
        target=backup_worker.run,
        args=(app.database,),
        daemon=True,
    )
    _worker_thread.start()

if __name__ == "__main__":
    app.run(host='0.0.0.0', port=9881, threaded=True)

